"""Public product copy, grounded in the Nexora console and API implementations."""

from html import escape


def link(path, label, style="text-link"):
    return f'<a class="{style}" href="@root@{path}">{label}<span aria-hidden="true">↗</span></a>'


def heading(eyebrow, title, text=""):
    return f'<div class="section-heading"><p class="eyebrow">{eyebrow}</p><h2>{title}</h2>{f"<p>{text}</p>" if text else ""}</div>'


def cards(items, cls="feature-grid"):
    return f'<div class="{cls}">' + "".join(
        f'<article class="feature-card"><span class="card-index">{i:02d} /</span><h3>{title}</h3><p>{text}</p>{link(path, "Explore " + label) if path else ""}</article>'
        for i, (title, text, path, label) in enumerate(items, 1)
    ) + '</div>'


def checklist(items):
    return '<ul class="check-list">' + ''.join(f'<li>{item}</li>' for item in items) + '</ul>'


def flow(steps, label="Workflow illustration"):
    return f'<div class="flow" role="img" aria-label="{escape(label)}">' + ''.join(
        f'<div class="flow-step"><span>{i:02d}</span><strong>{title}</strong><small>{text}</small></div>'
        for i, (title, text) in enumerate(steps, 1)
    ) + '</div>'


def art(name, caption, theme=""):
    return f'<figure class="art-frame {theme}"><img src="@root@assets/{name}.svg" alt="{escape(caption)}" loading="lazy" width="960" height="640"><figcaption>{caption}</figcaption></figure>'


def split(eyebrow, title, text, items, image, caption, reverse=False):
    return f'<section class="section split {"reverse" if reverse else ""}"><div>{heading(eyebrow, title, text)}{checklist(items)}</div>{art(image, caption)}</section>'


def note(title, text):
    return f'<aside class="note"><span class="note-mark" aria-hidden="true">↳</span><div><h3>{title}</h3><p>{text}</p></div></aside>'


